#!/usr/bin/env node
/**
 * Generates the site's Getting Started page from the shipped pncli skill.
 *
 * Source of truth is `skills/pncli/SKILL.md` — the same file agents read after
 * `pncli skills install`. It replaced `copilot-instructions.md` (retired in
 * #388) so the site and the skill can no longer drift apart.
 *
 * The per-service files (`skills/pncli/<service>.md`) are not inlined here: the
 * site's own `/commands/` page, generated by parse-commands.mjs, already covers
 * every command and flag, and duplicating it would recreate the two-generators
 * problem this change removed.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const srcPath = join(__dirname, '../../skills/pncli/SKILL.md');
const outDir  = join(__dirname, '../src/content/docs');
const outFile = join(outDir, 'getting-started.mdx');

const raw = readFileSync(srcPath, 'utf8');

// Services hidden from the public site. SKILL.md is untouched; mentions are
// stripped from the rendered page only (their command reference is dropped
// separately via the parse-commands SKIP list).
// Remove a name here to bring a service back onto the site.
const HIDDEN_SERVICES = [];

function hideHiddenServices(text) {
  for (const svc of HIDDEN_SERVICES) {
    // Drop the service's row from the "Available services" table. This runs
    // before dropServiceFileColumn, so split('|')[1] is still the Service cell.
    text = text
      .split('\n')
      .filter((line) => !(line.startsWith('|') && line.split('|')[1]?.trim() === svc))
      .join('\n');
    // Drop mentions from comma-separated prose lists. The ", and X" form has to
    // go first: the intro sentence ends "..., LogScale, Split.IO, and Figma.",
    // so matching only ", X" would leave a dangling "and" — or the service name
    // itself, which is the leak this list exists to prevent.
    text = text
      .replaceAll(`, and ${svc}`, '')
      .replaceAll(`and ${svc}`, '')
      .replaceAll(`${svc}, `, '')
      .replaceAll(`, ${svc}`, '');
  }
  return text;
}

// Strip the YAML frontmatter block — it is skill metadata, not page content.
function stripFrontmatter(text) {
  if (!text.startsWith('---\n')) return text;
  const end = text.indexOf('\n---\n', 4);
  if (end === -1) return text;
  return text.slice(end + 5);
}

// The "Available services" table has a `File` column naming the per-service
// markdown file inside the installed skill. On the site those filenames point
// at nothing, so drop that column and keep Service + Commands unlocked.
const SERVICES_HEADING = '## Available services';

function dropServiceFileColumn(text) {
  let inServicesSection = false;

  return text
    .split('\n')
    .map((line) => {
      // Only transform the table under "## Available services". Scoping this by
      // section matters: the separator-row pattern below matches ANY 3-column
      // table, and rewriting a 3-column header to 2 columns while leaving its
      // separator at 3 stops GFM rendering it as a table at all. Unscoped, the
      // next 3-column table added to SKILL.md would silently break.
      if (line.startsWith('## ')) {
        inServicesSection = line.trim() === SERVICES_HEADING;
        return line;
      }
      if (!inServicesSection || !line.startsWith('|')) return line;

      const cells = line.split('|');
      // ['', service, file, commands, ''] — only rewrite rows of that exact shape
      if (cells.length !== 5) return line;
      if (!/`[\w.-]+\.md`|^\s*File\s*$|^\s*:?-+:?\s*$/.test(cells[2])) return line;
      return [cells[0], cells[1], cells[3], cells[4]].join('|');
    })
    .join('\n');
}

// Escape MDX footguns outside fenced code blocks and outside inline code spans.
// Walk line-by-line: toggle inFence on ``` lines, then on non-fence lines escape
// bare angle brackets and curly braces that MDX would misparse as JSX.
function escapeMdxOutsideFences(text) {
  const lines = text.split('\n');
  let inFence = false;
  const result = [];

  for (const line of lines) {
    // Toggle fence state on lines that start a fenced code block (``` or ~~~)
    if (/^(`{3,}|~{3,})/.test(line)) {
      inFence = !inFence;
      result.push(line);
      continue;
    }

    if (inFence) {
      result.push(line);
      continue;
    }

    // Preserve blockquote markers ("> " prefixes) so they render as real
    // blockquotes instead of an escaped literal "&gt;" in the output.
    const bqMatch = line.match(/^(\s{0,3}(?:>\s?)+)(.*)$/);
    const bqPrefix = bqMatch ? bqMatch[1] : '';
    const rest = bqMatch ? bqMatch[2] : line;

    // Outside fences: escape characters inside inline code spans, then outside
    // Split on inline code spans (backtick-delimited), escape only the non-code parts
    const parts = rest.split(/(`[^`]+`)/);
    const escaped = parts.map((part, i) => {
      // Odd indices are backtick-wrapped (inline code) — leave them as-is
      if (i % 2 === 1) return part;
      return part
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/\{/g, '&#123;')
        .replace(/\}/g, '&#125;');
    }).join('');
    result.push(bqPrefix + escaped);
  }

  return result.join('\n');
}

// Splice a component in before a heading, or append it if that heading moved or
// was renamed in SKILL.md — a missing callout should not fail the site build.
function insertBefore(body, heading, component) {
  const idx = body.indexOf(heading);
  if (idx === -1) {
    console.warn(`parse-instructions: WARNING — "${heading.trim()}" not found in SKILL.md; appending ${component}`);
    return [body, component].join('\n\n');
  }
  return [body.slice(0, idx).trimEnd(), component, body.slice(idx).trimStart()].join('\n\n');
}

const INTRO = [
  'This page is generated from the pncli skill (`skills/pncli/SKILL.md`) — the same',
  'file your agent reads after `pncli skills install`. Install the skill to get it,',
  'plus a per-service setup file for every integration below, directly in your repo.',
].join('\n');

let body = escapeMdxOutsideFences(
  dropServiceFileColumn(hideHiddenServices(stripFrontmatter(raw))).trim()
);

body = insertBefore(body, '## Installing skills', '<CommandReferenceCallout />');
body = insertBefore(body, '## Setup walkthrough', '<ConfigSetupCallout />');

const mdx = [
  '---',
  'title: "Getting Started"',
  'description: "Setup, conventions, and tips for using pncli with AI agents and in the terminal."',
  `generatedAt: "${new Date().toISOString()}"`,
  '---',
  '',
  "import CommandReferenceCallout from '../../components/CommandReferenceCallout.astro';",
  "import ConfigSetupCallout from '../../components/ConfigSetupCallout.astro';",
  '',
  INTRO,
  '',
  body.trim(),
  '',
].join('\n');

mkdirSync(outDir, { recursive: true });
writeFileSync(outFile, mdx);
console.log('parse-instructions: wrote getting-started.mdx from skills/pncli/SKILL.md');
